            db.fetchMonthlyReports(selectedMonth)
          ]);

          setEmployees(empData);
          setJobs(jobsData);
          setEntries(entriesData);
          setMonthStatuses(statusesData);

          if (empData.length > 0) {
             const savedUserId = localStorage.getItem('lastUserId');
             const userExists = empData.find(e => String(e.id) === String(savedUserId));
             const defaultId = String(userExists ? savedUserId : empData[0].id);
             if (!currentUserId) setCurrentUserId(defaultId);
          }
        } catch (err: any) {
          setLoadError(err.message || "Nepodařilo se načíst data.");
        }
      } else {
        setLoadError(`Připojení selhalo: ${conn.message}`);
      }
      setIsLoading(false);
    };

    loadData();
  }, [selectedMonth]);

  useEffect(() => {
    if (currentUserId) localStorage.setItem('lastUserId', currentUserId);
  }, [currentUserId]);

  const currentUser = useMemo(() => {
    const list = useDemoData ? MOCK_EMPLOYEES : employees;
    const found = list.find(e => String(e.id) === String(currentUserId));
    return found || list[0] || MOCK_EMPLOYEES[0];
  }, [useDemoData, employees, currentUserId]);

  const targetUserId = reviewingUserId || currentUserId;
  const targetUser = (useDemoData ? MOCK_EMPLOYEES : employees).find(e => String(e.id) === String(targetUserId)) || currentUser;
  const isManagerMode = currentUser.role === 'Manager';

  // Aktuální stav měsíce pro cílového uživatele
  const currentMonthStatus = useMemo(() => {
    const status = monthStatuses.find(s => String(s.employeeId) === String(targetUserId) && s.month === selectedMonth);
    return status || { employeeId: targetUserId, month: selectedMonth, status: TimesheetStatus.DRAFT };
  }, [monthStatuses, targetUserId, selectedMonth]);

  // Docházka je uzamčena pokud je odeslána nebo schválena (a nejsme Lucie v režimu revize)
  const isLocked = useMemo(() => {
    const isSubmittedOrApproved = currentMonthStatus.status === TimesheetStatus.SUBMITTED || 
                                currentMonthStatus.status === TimesheetStatus.APPROVED;
    // Manažer může editovat i odeslanou docházku během kontroly
    if (isManagerMode && reviewingUserId) return false; 
    return isSubmittedOrApproved;
  }, [currentMonthStatus, isManagerMode, reviewingUserId]);

  const monthlyUserEntries = useMemo(() => 
    entries.filter(e => String(e.employeeId) === String(targetUserId) && e.date.startsWith(selectedMonth)), 
  [entries, targetUserId, selectedMonth]);

  const validationIssues = useMemo(() => {
    const [year, month] = selectedMonth.split('-');
    return validateMonth(monthlyUserEntries, year, month);
  }, [monthlyUserEntries, selectedMonth]);

  const handleUpdateStatus = async (newStatus: TimesheetStatus, comment?: string) => {
    const updatedStatus: MonthStatus = {
      ...currentMonthStatus,
      status: newStatus,
      managerComment: comment,
      submittedAt: newStatus === TimesheetStatus.SUBMITTED ? new Date().toISOString() : currentMonthStatus.submittedAt,
      approvedAt: newStatus === TimesheetStatus.APPROVED ? new Date().toISOString() : currentMonthStatus.approvedAt,
    };

    if (!useDemoData) {
      try {
        await db.upsertMonthlyReport(updatedStatus);
      } catch (e: any) {
        alert("Nepodařilo se uložit stav: " + e.message);
        return;
      }
    }

    setMonthStatuses(prev => [
      ...prev.filter(s => !(String(s.employeeId) === String(targetUserId) && s.month === selectedMonth)),
      updatedStatus
    ]);

    if (newStatus === TimesheetStatus.APPROVED || newStatus === TimesheetStatus.REJECTED) {
      setReviewingUserId(null); // Zavřít kontrolu po akci
    }
  };

  const handleModalSubmit = async (date: string, submittedEntries: TimeEntry[]) => {
      if (isLocked) return;

      if (!useDemoData) {
        try {
          if (editingEntry) {
              await db.deleteTimeEntry(editingEntry.id);
          } else if (date !== 'BULK_RANGE') {
              await db.deleteTimeEntriesForDate(String(targetUserId), date);
          }
          await db.addTimeEntriesBulk(submittedEntries);
        } catch (e: any) {
          alert(`Chyba synchronizace s DB: ${e.message}`);
          return;
        }
      }

      if (date === 'BULK_RANGE') {
          setEntries(prev => [...prev, ...submittedEntries]);
      } else {
          setEntries(prev => [
              ...prev.filter(e => !(String(e.employeeId) === String(targetUserId) && (editingEntry ? e.id === editingEntry.id : e.date === date))),
              ...submittedEntries
          ]);
      }
      setEditingEntry(undefined);
  };

  const handleDeleteEntry = async (id: string) => {
    if (isLocked) return;
    if (!useDemoData) {
      try { await db.deleteTimeEntry(id); } catch (e) { return; }
    }
    setEntries(prev => prev.filter(e => e.id !== id));
  };

  const handleEditEntry = (entry: TimeEntry) => {
    if (isLocked) return;
    setEditingEntry(entry);
    setIsEntryModalOpen(true);
  };

  return (
    <div className="flex flex-col md:flex-row min-h-screen bg-gray-50">
      <Sidebar 
        activeTab={activeTab} setActiveTab={setActiveTab} 
        currentUser={currentUser} 
        employees={(useDemoData ? MOCK_EMPLOYEES : employees).filter(e => e.isActive)}
        onRequestSwitchUser={(id) => {
            const list = useDemoData ? MOCK_EMPLOYEES : employees;
            const targetEmp = list.find(e => String(e.id) === String(id));
            if (targetEmp?.pinCode) { 
                setPendingUserId(id); 
                setIsPinModalOpen(true); 
            } else {
                setCurrentUserId(id);
            }
        }} 
        onShowAbout={() => setIsAboutOpen(true)}
        version="2.0.2"
        isConnected={isConnected}
      />

      <main className="flex-1 overflow-y-auto no-print">
        {isLoading && (
          <div className="fixed inset-0 bg-white/80 backdrop-blur-sm z-[90] flex items-center justify-center">
            <div className="flex flex-col items-center">
              <div className="w-12 h-12 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin mb-4"></div>
              <p className="font-bold text-slate-700">Synchronizace...</p>
            </div>
          </div>
        )}

        {reviewingUserId && (
          <div className="bg-indigo-600 text-white px-6 py-3 sticky top-0 z-40 flex justify-between items-center shadow-md">
             <div className="font-bold text-sm flex items-center gap-2">
                <span className="bg-white/20 p-1 rounded">👁️</span> 
                Kontrola docházky: {targetUser.name}
             </div>
             <button onClick={() => setReviewingUserId(null)} className="bg-white text-indigo-600 px-4 py-1.5 rounded-lg text-xs font-bold shadow-sm">UKONČIT KONTROLU</button>
          </div>
        )}

        {activeTab === 'overview' && (
          <div className="p-4 md:p-8">
            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-4">
              <h2 className="text-2xl font-bold text-slate-900">Přehled docházky</h2>
              <MonthNavigator selectedMonth={selectedMonth} onMonthChange={setSelectedMonth} />
            </div>

            <ApprovalWorkflow 
              status={currentMonthStatus} 
              onUpdateStatus={handleUpdateStatus} 
              isManagerMode={isManagerMode} 
              isReviewing={!!reviewingUserId}
            />

            {isManagerMode && !reviewingUserId && employees.length > 0 && (
                <TeamOverview 
                  employees={employees} 
                  allEntries={entries} 
                  selectedMonth={selectedMonth} 
                  onInspect={setReviewingUserId} 
                  currentUserRole={currentUser.role}
                  statuses={monthStatuses}
                />
            )}

            {!isLocked ? (
              <SmartInput 
                onEntriesAdded={(newE) => {
                  if (!useDemoData) db.addTimeEntriesBulk(newE);
                  setEntries(prev => [...prev, ...newE]);
                }} 
                currentUserId={String(targetUserId)} 
                onManualEntry={() => {setEditingEntry(undefined); setIsEntryModalOpen(true);}} 
              />
            ) : (
              <div className="bg-amber-50 border border-amber-200 p-6 rounded-xl mb-6 flex items-center gap-4">
                <div className="text-2xl">🔒</div>
                <div>
                  <h3 className="font-bold text-amber-900">Docházka je uzamčena</h3>
                  <p className="text-sm text-amber-700">Záznamy již byly odeslány ke schválení nebo uzavřeny. Pro změny kontaktujte Lucii.</p>
                </div>
              </div>
            )}

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mb-8">
                <div className="lg:col-span-2"><Dashboard entries={monthlyUserEntries} selectedMonth={selectedMonth} /></div>
                <div><ValidationStatus issues={validationIssues} /></div>
            </div>

            <h3 className="text-lg font-semibold text-slate-900 mb-4 flex items-center gap-2">
              Výkaz: {targetUser.name}
              {isLocked && <span className="text-[10px] bg-slate-200 text-slate-600 px-2 py-0.5 rounded uppercase font-bold">Pouze pro čtení</span>}
            </h3>
            <TimesheetTable 
              entries={monthlyUserEntries} 
              onDelete={handleDeleteEntry} 
              onEdit={handleEditEntry} 
              isLocked={isLocked}
            />
          </div>
        )}

        {activeTab === 'report' && (
           <div className="p-4 md:p-8">
              <ReportingModule 
                entries={entries} 
                employees={employees} 
                currentUserRole={currentUser.role} 
                jobs={jobs} 
                selectedEmployeeId={String(targetUserId)} 
                selectedMonth={selectedMonth} 
                monthStatus={currentMonthStatus}
              />
           </div>
        )}

        {activeTab === 'settings' && isManagerMode && (
           <div className="p-4 md:p-8"><AdminPanel employees={employees} jobs={jobs} /></div>
        )}
      </main>

      <EntryFormModal 
        isOpen={isEntryModalOpen} 
        onClose={() => {setIsEntryModalOpen(false); setEditingEntry(undefined);}} 
        onSubmit={handleModalSubmit} 
        currentUserId={String(targetUserId)} 
        jobs={jobs} 
        initialEntry={editingEntry} 
      />

      <PinPadModal 
        isOpen={isPinModalOpen} 
        onClose={() => setIsPinModalOpen(false)} 
        onSuccess={() => {setCurrentUserId(pendingUserId!); setIsPinModalOpen(false);}} 
        targetPin={(employees.find(e=>String(e.id)===String(pendingUserId)) || MOCK_EMPLOYEES.find(e=>String(e.id)===String(pendingUserId)))?.pinCode || ""} 
        targetUserName={(employees.find(e=>String(e.id)===String(pendingUserId)) || MOCK_EMPLOYEES.find(e=>String(e.id)===String(pendingUserId)))?.name || ""} 
      />

      <HelpSystem />
      <AboutModal isOpen={isAboutOpen} onClose={() => setIsAboutOpen(false)} version="2.0.2" />
      <MobileNavigation activeTab={activeTab} setActiveTab={setActiveTab} currentUserRole={currentUser.role} />
    </div>
  );
};

export default App;

import React, { useMemo } from 'react';
import { TimeEntry, Employee, Job, WorkType, MonthStatus, TimesheetStatus } from '../types';
import { getHolidayName } from '../services/holidayService';

interface ReportingModuleProps {
  entries: TimeEntry[];
  employees: Employee[];
  currentUserRole: string;
  jobs: Job[];
  selectedEmployeeId?: string;
  selectedMonth?: string;
  monthStatus?: MonthStatus;
}

const ReportingModule: React.FC<ReportingModuleProps> = ({ entries, employees, selectedEmployeeId, selectedMonth, monthStatus }) => {
  const monthStr = selectedMonth || new Date().toISOString().slice(0, 7);
  const [year, month] = monthStr.split('-').map(Number);

  const employee = useMemo(() => 
    employees.find(e => String(e.id) === String(selectedEmployeeId)) || employees[0], 
  [employees, selectedEmployeeId]);

  const filteredEntries = useMemo(() => 
    entries.filter(e => String(e.employeeId) === String(employee?.id) && e.date.startsWith(monthStr)),
  [entries, employee, monthStr]);

  const monthStats = useMemo(() => {
    const daysInMonth = new Date(year, month, 0).getDate();
    let workingDays = 0;
    const days = [];

    for (let d = 1; d <= daysInMonth; d++) {
      const dateStr = `${year}-${String(month).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
      const dateObj = new Date(year, month - 1, d);
      const isWeekend = dateObj.getDay() === 0 || dateObj.getDay() === 6;
      const holiday = getHolidayName(dateStr);
      if (!isWeekend && !holiday) workingDays++;

      days.push({
        dateStr,
        isWeekend,
        holiday,
        entries: filteredEntries.filter(e => e.date === dateStr)
      });
    }

    const fund = workingDays * 8;
    const totalHours = filteredEntries.reduce((sum, e) => sum + e.hours, 0);
    return { fund, totalHours, days, diff: totalHours - fund };
  }, [year, month, filteredEntries]);

  const typeSummary = useMemo(() => {
    const summary: Record<string, number> = {};
    Object.values(WorkType).forEach(t => summary[t] = 0);
    filteredEntries.forEach(e => summary[e.type] += e.hours);
    return summary;
  }, [filteredEntries]);

  const jobSummary = useMemo(() => {
    const summary: Record<string, { regular: number, overtime: number }> = {};
    filteredEntries.forEach(e => {
      if (!summary[e.project]) summary[e.project] = { regular: 0, overtime: 0 };
      if (e.type === WorkType.OVERTIME) summary[e.project].overtime += e.hours;
      else summary[e.project].regular += e.hours;
    });
    return summary;
  }, [filteredEntries]);

  const shorten = (text: string, len: number = 25) => 
    text.length > len ? text.substring(0, len - 3) + '...' : text;

  return (
    <div className="space-y-6 max-w-5xl mx-auto pb-20">
      <div className="bg-white p-6 rounded-xl border border-gray-200 shadow-sm flex justify-between items-center no-print">
        <div>
          <h2 className="text-xl font-bold text-slate-900">Mzdový report</h2>
          <p className="text-xs text-slate-500">Zaměstnanec: {employee?.name} | {monthStr}</p>
        </div>
        <button onClick={() => window.print()} className="bg-indigo-600 hover:bg-indigo-700 text-white px-6 py-2 rounded-lg font-bold text-sm transition-colors shadow-lg">Vytisknout A4</button>
      </div>

      <div className="bg-white p-6 md:p-8 rounded-none md:rounded-xl shadow-none md:shadow-sm border-0 md:border border-gray-100 print:p-0 print:m-0 relative overflow-hidden">

        {/* Stavové razítko pro tisk */}
        {monthStatus?.status === TimesheetStatus.APPROVED && (
          <div className="absolute top-10 right-10 border-4 border-green-600/30 text-green-600/30 font-black text-4xl px-4 py-2 rounded-xl -rotate-12 pointer-events-none select-none uppercase tracking-widest hidden print:block">
            SCHVÁLENO
          </div>
        )}

        <div className="flex justify-between items-start border-b-2 border-slate-900 pb-4 mb-6">
          <div>
            <h1 className="text-2xl font-black text-slate-900 uppercase">Výkaz práce</h1>
            <p className="text-sm font-bold text-indigo-600">{employee?.name}</p>
          </div>
          <div className="text-right">
            <p className="text-xl font-black text-slate-900">{monthStr}</p>
            <p className="text-[10px] text-slate-400 uppercase font-bold">Export: {new Date().toLocaleDateString('cs-CZ')}</p>
          </div>
        </div>

        <div className="grid grid-cols-4 gap-4 mb-8">
          <div className="border-l-4 border-indigo-600 pl-3">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">Celkem hodin</p>
            <p className="text-2xl font-black text-slate-900">{monthStats.totalHours.toFixed(1)}h</p>
          </div>
          <div className="border-l-4 border-slate-300 pl-3">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">Fond</p>
            <p className="text-2xl font-black text-slate-900">{monthStats.fund}h</p>
          </div>
          <div className="border-l-4 border-orange-500 pl-3">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">Přesčasy</p>
            <p className="text-2xl font-black text-orange-600">{typeSummary[WorkType.OVERTIME].toFixed(1)}h</p>
          </div>
          <div className={`border-l-4 pl-3 ${monthStats.diff >= 0 ? 'border-green-500' : 'border-red-500'}`}>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">Rozdíl</p>
            <p className={`text-2xl font-black ${monthStats.diff >= 0 ? 'text-green-600' : 'text-red-600'}`}>
              {monthStats.diff > 0 ? '+' : ''}{monthStats.diff.toFixed(1)}h
            </p>
          </div>
        </div>

        <div className="grid grid-cols-2 gap-8 mb-8">
          <div>
            <h3 className="text-xs font-black text-slate-900 uppercase mb-3 bg-slate-100 p-2 border-l-2 border-slate-900">Mzdové ukazatele</h3>
            <div className="grid grid-cols-2 gap-x-6 gap-y-1">
              {Object.entries(typeSummary).filter(([_, h]) => h > 0).map(([type, hours]) => (
                <div key={type} className="flex justify-between border-b border-slate-100 py-1">
                  <span className="text-xs text-slate-600">{type}</span>
                  <span className="text-xs font-bold text-slate-900">{hours.toFixed(1)}h</span>
                </div>
              ))}
            </div>
          </div>
          <div>
            <h3 className="text-xs font-black text-slate-900 uppercase mb-3 bg-slate-100 p-2 border-l-2 border-slate-900">Přehled zakázek</h3>
            <table className="w-full text-left">
              <thead><tr className="border-b border-slate-200"><th className="text-[9px] font-black py-1">ZAKÁZKA</th><th className="text-[9px] font-black py-1 text-right">BĚŽNÁ</th><th className="text-[9px] font-black py-1 text-right text-orange-600">PŘESČAS</th></tr></thead>
              <tbody className="divide-y divide-slate-50">
                {Object.entries(jobSummary).map(([name, data]) => (
                  <tr key={name}>
                    <td className="text-[10px] py-1">{shorten(name)}</td>
                    <td className="text-[10px] py-1 text-right font-medium">{data.regular.toFixed(1)}h</td>
                    <td className="text-[10px] py-1 text-right font-bold text-orange-600">{data.overtime > 0 ? data.overtime.toFixed(1) + 'h' : '-'}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        <div>
          <h3 className="text-xs font-black text-slate-900 uppercase mb-3 bg-slate-100 p-2 border-l-2 border-slate-900">Denní detail docházky</h3>
          <table className="w-full border-collapse">
            <thead><tr className="bg-slate-800 text-white"><th className="text-[9px] p-1.5 text-left w-20">DATUM</th><th className="text-[9px] p-1.5 text-left">PROJEKT</th><th className="text-[9px] p-1.5 text-left w-24">DRUH</th><th className="text-[9px] p-1.5 text-right w-16">HODINY</th></tr></thead>
            <tbody className="divide-y divide-slate-200 border-b border-slate-200">
              {monthStats.days.map(day => {
                const rowEntries = day.entries;
                const totalDayHours = rowEntries.reduce((s, e) => s + e.hours, 0);
                return (
                  <tr key={day.dateStr} className={`${day.isWeekend ? 'bg-slate-50' : ''} ${day.holiday ? 'bg-amber-50' : ''}`}>
                    <td className="text-[10px] p-1.5 font-bold">{new Date(day.dateStr).toLocaleDateString('cs-CZ', { day: '2-digit', month: '2-digit', weekday: 'short' })}</td>
                    <td className="text-[10px] p-1.5">
                      {rowEntries.length > 0 ? rowEntries.map((e, idx) => (
                        <div key={idx} className="flex gap-2"><span>{shorten(e.project, 40)}</span></div>
                      )) : <span className="text-slate-300 italic">{day.holiday || (day.isWeekend ? 'Víkend' : '-')}</span>}
                    </td>
                    <td className="text-[9px] p-1.5 text-slate-500">{rowEntries.map((e, i) => <div key={i}>{e.type}</div>)}</td>
                    <td className="text-[10px] p-1.5 text-right font-black">{totalDayHours > 0 ? `${totalDayHours.toFixed(1)}h` : ''}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>

        <div className="mt-12 flex justify-between gap-12 border-t border-slate-100 pt-8">
          <div className="flex-1 border-t border-slate-300 pt-2">
            <p className="text-[9px] font-bold text-slate-400 uppercase">Podpis zaměstnance</p>
          </div>
          <div className="flex-1 border-t border-slate-300 pt-2 text-right">
            <p className="text-[9px] font-bold text-slate-400 uppercase">Schválil (manažer)</p>
            {monthStatus?.status === TimesheetStatus.APPROVED && (
              <p className="text-[10px] font-black text-slate-900 mt-2">ELEKTRONICKY SCHVÁLENO</p>
            )}
          </div>
        </div>

      </div>
    </div>
  );
};
export default ReportingModule;

import React from 'react';
import { Employee, TimeEntry, MonthStatus, TimesheetStatus } from '../types';

interface TeamOverviewProps {
  employees: Employee[];
  allEntries: TimeEntry[];
  selectedMonth: string;
  onInspect: (id: string) => void;
  currentUserRole: string;
  statuses: MonthStatus[];
}

const TeamOverview: React.FC<TeamOverviewProps> = ({ employees, selectedMonth, onInspect, statuses }) => {
  const getStatusBadge = (empId: string) => {
    const status = statuses.find(s => String(s.employeeId) === String(empId) && s.month === selectedMonth);
    switch (status?.status) {
      case TimesheetStatus.SUBMITTED:
        return <span className="bg-amber-100 text-amber-700 px-2 py-0.5 rounded text-[9px] font-black border border-amber-200 animate-pulse">KE SCHVÁLENÍ</span>;
      case TimesheetStatus.APPROVED:
        return <span className="bg-green-100 text-green-700 px-2 py-0.5 rounded text-[9px] font-black border border-green-200">SCHVÁLENO</span>;
      case TimesheetStatus.REJECTED:
        return <span className="bg-red-100 text-red-700 px-2 py-0.5 rounded text-[9px] font-black border border-red-200">VRÁCENO</span>;
      default:
        return <span className="bg-slate-100 text-slate-400 px-2 py-0.5 rounded text-[9px] font-black border border-slate-200">ROZPRACOVÁNO</span>;
    }
  };

  return (
    <div className="bg-white rounded-2xl border border-gray-200 shadow-sm overflow-hidden mb-8">
      <div className="p-4 bg-slate-50 border-b border-gray-200 flex justify-between items-center">
        <h3 className="font-bold text-sm text-slate-700">Týmový přehled – Lucie</h3>
        <span className="text-[10px] text-slate-400 font-bold uppercase">{selectedMonth}</span>
      </div>
      <div className="overflow-x-auto">
        <table className="w-full text-sm">
          <tbody className="divide-y divide-gray-100">
            {employees.filter(e => e.role !== 'Manager').map(e => (
              <tr key={e.id} className="hover:bg-slate-50 transition-colors">
                <td className="p-4 flex items-center gap-3">
                  <div className="relative">
                    <img src={e.avatar} className="w-9 h-9 rounded-full border border-slate-200" alt="" />
                    {statuses.find(s => String(s.employeeId) === String(e.id) && s.month === selectedMonth)?.status === TimesheetStatus.SUBMITTED && (
                      <span className="absolute -top-1 -right-1 w-3 h-3 bg-amber-500 rounded-full border-2 border-white"></span>
                    )}
                  </div>
                  <div>
                    <div className="font-bold text-slate-900">{e.name}</div>
                    <div className="text-[10px] text-slate-400">{e.email}</div>
                  </div>
                </td>
                <td className="p-4 text-center">
                  {getStatusBadge(String(e.id))}
                </td>
                <td className="p-4 text-right">
                  <button 
                    onClick={() => onInspect(String(e.id))} 
                    className="bg-white border border-slate-200 hover:border-indigo-600 hover:text-indigo-600 text-slate-600 px-4 py-1.5 rounded-lg font-bold text-[10px] uppercase tracking-wider transition-all shadow-sm"
                  >
                    Zkontrolovat
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default TeamOverview;

import { createClient } from '@supabase/supabase-js';
import { CREDENTIALS } from '../credentials';
import { Employee, Job, TimeEntry, MonthStatus, Notification } from '../types';

const supabaseUrl = CREDENTIALS.SUPABASE_URL;
const supabaseKey = CREDENTIALS.SUPABASE_KEY;

export const supabase = (supabaseUrl && supabaseKey) 
  ? createClient(supabaseUrl, supabaseKey) 
  : null;

// Robustní transformace snake_case -> camelCase
const toCamel = (obj: any): any => {
  if (obj === null || typeof obj !== 'object' || obj instanceof Date) return obj;
  if (Array.isArray(obj)) return obj.map(toCamel);

  const n: any = {};
  Object.keys(obj).forEach(k => {
    const camel = k.replace(/([-_][a-z])/ig, ($1) => $1.toUpperCase().replace('-', '').replace('_', ''));
    n[camel] = toCamel(obj[k]);
  });
  return n;
};

// Robustní transformace camelCase -> snake_case
const toSnake = (obj: any): any => {
  if (obj === null || typeof obj !== 'object' || obj instanceof Date) return obj;
  if (Array.isArray(obj)) return obj.map(toSnake);

  const n: any = {};
  Object.keys(obj).forEach(k => {
    const snake = k.replace(/[A-Z]/g, letter => `_${letter.toLowerCase()}`);
    n[snake] = toSnake(obj[k]);
  });
  return n;
};

export const checkConnection = async () => {
  if (!supabase) return { success: false, message: 'Klient nebyl vytvořen (chybí klíče).' };
  try {
    const { error } = await supabase.from('employees').select('id').limit(1);
    if (error) throw error;
    return { success: true, message: 'Připojeno k Supabase.' };
  } catch (err: any) {
    return { success: false, message: err.message || 'Nepodařilo se navázat spojení.' };
  }
};

export const fetchEmployees = async (): Promise<Employee[]> => {
  if (!supabase) return [];
  const { data, error } = await supabase.from('employees').select('*').order('name');
  if (error) throw new Error(`Zaměstnanci: ${error.message}`);
  return toCamel(data) || [];
};

export const addEmployee = async (emp: Employee) => {
  if (!supabase) return;
  const { error } = await supabase.from('employees').insert([toSnake(emp)]);
  if (error) throw error;
};

export const updateEmployee = async (emp: Employee) => {
  if (!supabase) return;
  const { error } = await supabase.from('employees').update(toSnake(emp)).eq('id', emp.id);
  if (error) throw error;
};

export const updateEmployeeStatus = async (id: string, isActive: boolean) => {
  if (!supabase) return;
  const { error } = await supabase.from('employees').update({ is_active: isActive }).eq('id', id);
  if (error) throw error;
};

export const fetchJobs = async (): Promise<Job[]> => {
  if (!supabase) return [];
  const { data, error } = await supabase.from('jobs').select('*').order('code');
  if (error) throw new Error(`Zakázky: ${error.message}`);
  return toCamel(data) || [];
};

export const addJob = async (job: Job) => {
  if (!supabase) return;
  const { error } = await supabase.from('jobs').insert([toSnake(job)]);
  if (error) throw error;
};

export const updateJobStatus = async (id: string, isActive: boolean) => {
  if (!supabase) return;
  const { error } = await supabase.from('jobs').update({ is_active: isActive }).eq('id', id);
  if (error) throw error;
};

export const fetchTimeEntries = async (employeeId?: string, month?: string): Promise<TimeEntry[]> => {
  if (!supabase) return [];
  let query = supabase.from('time_entries').select('*');

  if (employeeId) {
    query = query.eq('employee_id', employeeId);
  }

  if (month) {
    const [year, monthNum] = month.split('-').map(Number);
    const startDate = `${month}-01`;
    // Získání posledního dne měsíce (0. den následujícího měsíce)
    const lastDay = new Date(year, monthNum, 0).getDate();
    const endDate = `${month}-${String(lastDay).padStart(2, '0')}`;
    query = query.gte('date', startDate).lte('date', endDate);
  }

  const { data, error } = await query.order('date', { ascending: false });
  if (error) throw new Error(`Záznamy: ${error.message}`);
  return toCamel(data) || [];
};

export const addTimeEntriesBulk = async (entries: TimeEntry[]) => {
  if (!supabase) return;
  const snakeEntries = entries.map(e => toSnake(e));
  const { error } = await supabase.from('time_entries').insert(snakeEntries);
  if (error) throw error;
};

export const deleteTimeEntriesForDate = async (employeeId: string, date: string) => {
  if (!supabase) return;
  const { error } = await supabase.from('time_entries').delete().eq('employee_id', employeeId).eq('date', date);
  if (error) throw error;
};

export const deleteTimeEntry = async (id: string) => {
  if (!supabase) return;
  const { error } = await supabase.from('time_entries').delete().eq('id', id);
  if (error) throw error;
};

export const fetchMonthlyReports = async (month: string): Promise<MonthStatus[]> => {
  if (!supabase) return [];
  const { data, error } = await supabase.from('month_status').select('*').eq('month', month);
  if (error) return [];
  return toCamel(data) || [];
};

export const upsertMonthlyReport = async (report: MonthStatus) => {
  if (!supabase) return;
  // Pro upsert v Supabase musíme mít buď ID nebo unikátní constraint (employee_id, month)
  const snakeReport = toSnake(report);
  const { error } = await supabase.from('month_status').upsert(snakeReport, {
    onConflict: 'employee_id,month'
  });
  if (error) throw error;
};

export const fetchNotifications = async (userId: string): Promise<Notification[]> => {
  if (!supabase) return [];
  const { data, error } = await supabase.from('notifications')
    .select('*')
    .eq('user_id', userId)
    .order('created_at', { ascending: false })
    .limit(20);
  if (error) return [];
  return toCamel(data) || [];
};

export const markNotificationAsRead = async (id: string) => {
  if (!supabase) return;
  const { error } = await supabase.from('notifications').update({ is_read: true }).eq('id', id);
  if (error) throw error;
};

export const createNotification = async (userId: string, message: string, type: string = 'info', senderId?: string) => {
  if (!supabase) return;
  const { error } = await supabase.from('notifications').insert([toSnake({
    userId,
    message,
    type,
    senderId,
    isRead: false,
    createdAt: new Date().toISOString()
  })]);
  if (error) throw error;
};

import React, { useState, useEffect, useMemo } from 'react';
import Sidebar from './components/Sidebar';
import SmartInput from './components/SmartInput';
import TimesheetTable from './components/TimesheetTable';
import Dashboard from './components/Dashboard';
import ReportingModule from './components/ReportingModule';
import ApprovalWorkflow from './components/ApprovalWorkflow';
import AdminPanel from './components/AdminPanel';
import MobileNavigation from './components/MobileNavigation';
import EntryFormModal from './components/EntryFormModal';
import ValidationStatus from './components/ValidationStatus';
import TeamOverview from './components/TeamOverview';
import HelpSystem from './components/HelpSystem';
import AboutModal from './components/AboutModal';
import NotificationBell from './components/NotificationBell';
import PinPadModal from './components/PinPadModal'; 
import MonthNavigator from './components/MonthNavigator';
import { TimeEntry, MonthStatus, TimesheetStatus, Employee, Job } from './types';
import { validateMonth } from './services/validationService';
import { isSupabaseConfigured } from './credentials';
import { MOCK_EMPLOYEES, MOCK_JOBS, MOCK_ENTRIES } from './services/mockData';
import * as db from './services/supabase';

const getCurrentMonth = () => new Date().toISOString().slice(0, 7);

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'overview' | 'report' | 'settings'>('overview');
  const [useDemoData, setUseDemoData] = useState(!isSupabaseConfigured());
  const [employees, setEmployees] = useState<Employee[]>(isSupabaseConfigured() ? [] : MOCK_EMPLOYEES);
  const [jobs, setJobs] = useState<Job[]>(isSupabaseConfigured() ? [] : MOCK_JOBS);
  const [entries, setEntries] = useState<TimeEntry[]>(isSupabaseConfigured() ? [] : MOCK_ENTRIES);
  const [monthStatuses, setMonthStatuses] = useState<MonthStatus[]>([]);
  const [isLoading, setIsLoading] = useState(isSupabaseConfigured());
  const [loadError, setLoadError] = useState<string | null>(null);
  const [currentUserId, setCurrentUserId] = useState<string>('');
  const [selectedMonth, setSelectedMonth] = useState<string>(getCurrentMonth());
  const [isEntryModalOpen, setIsEntryModalOpen] = useState(false);
  const [isAboutOpen, setIsAboutOpen] = useState(false);
  const [isPinModalOpen, setIsPinModalOpen] = useState(false);
  const [pendingUserId, setPendingUserId] = useState<string | null>(null);
  const [reviewingUserId, setReviewingUserId] = useState<string | null>(null);
  const [isConnected, setIsConnected] = useState(false);
  const [editingEntry, setEditingEntry] = useState<TimeEntry | undefined>(undefined);

  useEffect(() => {
    const loadData = async () => {
      setIsLoading(true);
      setLoadError(null);

      if (!isSupabaseConfigured()) {
        setIsLoading(false);
        if (!currentUserId && MOCK_EMPLOYEES.length > 0) setCurrentUserId(MOCK_EMPLOYEES[0].id);
        return;
      }

      try {
        const conn = await db.checkConnection();
        if (conn.success) {
          setUseDemoData(false);
          setIsConnected(true);

          const [empData, jobsData, entriesData, statusesData] = await Promise.all([
            db.fetchEmployees(),
            db.fetchJobs(),
            db.fetchTimeEntries(undefined, selectedMonth),
            db.fetchMonthlyReports(selectedMonth)
          ]);

          setEmployees(empData);
          setJobs(jobsData);
          setEntries(entriesData);
          setMonthStatuses(statusesData);

          const savedUserId = localStorage.getItem('lastUserId');
          if (empData.length > 0) {
            const userExists = empData.find(e => String(e.id) === String(savedUserId));
            const newId = String(userExists ? savedUserId : empData[0].id);
            if (currentUserId !== newId) setCurrentUserId(newId);
          }
        } else {
          setLoadError(`Spojení s DB: ${conn.message}`);
        }
      } catch (err: any) {
        setLoadError(err.message || "Nepodařilo se synchronizovat data.");
      } finally {
        setIsLoading(false);
      }
    };

    loadData();
  }, [selectedMonth]);

  useEffect(() => {
    if (currentUserId) localStorage.setItem('lastUserId', currentUserId);
  }, [currentUserId]);

  const currentUser = useMemo(() => {
    const list = useDemoData ? MOCK_EMPLOYEES : employees;
    const found = list.find(e => String(e.id) === String(currentUserId));
    return found || list[0] || MOCK_EMPLOYEES[0];
  }, [useDemoData, employees, currentUserId]);

  const targetUserId = reviewingUserId || currentUserId;
  const targetUser = useMemo(() => {
    const list = useDemoData ? MOCK_EMPLOYEES : employees;
    return list.find(e => String(e.id) === String(targetUserId)) || currentUser;
  }, [useDemoData, employees, targetUserId, currentUser]);

  const isManagerMode = currentUser.role === 'Manager';

  const currentMonthStatus = useMemo(() => {
    const status = monthStatuses.find(s => String(s.employeeId) === String(targetUserId) && s.month === selectedMonth);
    return status || { employeeId: targetUserId, month: selectedMonth, status: TimesheetStatus.DRAFT };
  }, [monthStatuses, targetUserId, selectedMonth]);

  const isLocked = useMemo(() => {
    const isSubmittedOrApproved = currentMonthStatus.status === TimesheetStatus.SUBMITTED || 
                                currentMonthStatus.status === TimesheetStatus.APPROVED;
    if (isManagerMode && reviewingUserId) return false; 
    return isSubmittedOrApproved;
  }, [currentMonthStatus, isManagerMode, reviewingUserId]);

  const monthlyUserEntries = useMemo(() => {
    return entries.filter(e => String(e.employeeId) === String(targetUserId) && e.date.startsWith(selectedMonth));
  }, [entries, targetUserId, selectedMonth]);

  const validationIssues = useMemo(() => {
    const [year, month] = selectedMonth.split('-');
    return validateMonth(monthlyUserEntries, year, month);
  }, [monthlyUserEntries, selectedMonth]);

  const handleUpdateStatus = async (newStatus: TimesheetStatus, comment?: string) => {
    const updatedStatus: MonthStatus = {
      ...currentMonthStatus,
      status: newStatus,
      managerComment: comment,
      submittedAt: newStatus === TimesheetStatus.SUBMITTED ? new Date().toISOString() : currentMonthStatus.submittedAt,
      approvedAt: newStatus === TimesheetStatus.APPROVED ? new Date().toISOString() : currentMonthStatus.approvedAt,
    };

    if (!useDemoData) {
      try {
        await db.upsertMonthlyReport(updatedStatus);
      } catch (e: any) {
        alert("Chyba při ukládání stavu: " + e.message);
        return;
      }
    }

    setMonthStatuses(prev => [
      ...prev.filter(s => !(String(s.employeeId) === String(targetUserId) && s.month === selectedMonth)),
      updatedStatus
    ]);

    if (newStatus === TimesheetStatus.APPROVED || newStatus === TimesheetStatus.REJECTED) {
      setReviewingUserId(null);
    }
  };

  const handleModalSubmit = async (date: string, submittedEntries: TimeEntry[]) => {
      if (isLocked) return;

      if (!useDemoData) {
        try {
          if (editingEntry) {
              await db.deleteTimeEntry(editingEntry.id);
          } else if (date !== 'BULK_RANGE') {
              await db.deleteTimeEntriesForDate(String(targetUserId), date);
          }
          await db.addTimeEntriesBulk(submittedEntries);
        } catch (e: any) {
          alert(`Chyba DB: ${e.message}`);
          return;
        }
      }

      if (date === 'BULK_RANGE') {
          setEntries(prev => [...prev, ...submittedEntries]);
      } else {
          setEntries(prev => [
              ...prev.filter(e => !(String(e.employeeId) === String(targetUserId) && (editingEntry ? e.id === editingEntry.id : e.date === date))),
              ...submittedEntries
          ]);
      }
      setEditingEntry(undefined);
  };

  const handleDeleteEntry = async (id: string) => {
    if (isLocked) return;
    if (!useDemoData) {
      try { await db.deleteTimeEntry(id); } catch (e) { return; }
    }
    setEntries(prev => prev.filter(e => e.id !== id));
  };

  const handleEditEntry = (entry: TimeEntry) => {
    if (isLocked) return;
    setEditingEntry(entry);
    setIsEntryModalOpen(true);
  };

  return (
    <div className="flex flex-col md:flex-row min-h-screen bg-gray-50">
      <Sidebar 
        activeTab={activeTab} setActiveTab={setActiveTab} 
        currentUser={currentUser} 
        employees={(useDemoData ? MOCK_EMPLOYEES : employees).filter(e => e.isActive)}
        onRequestSwitchUser={(id) => {
            const list = useDemoData ? MOCK_EMPLOYEES : employees;
            const targetEmp = list.find(e => String(e.id) === String(id));
            if (targetEmp?.pinCode) { 
                setPendingUserId(id); 
                setIsPinModalOpen(true); 
            } else {
                setCurrentUserId(id);
            }
        }} 
        onShowAbout={() => setIsAboutOpen(true)}
        version="2.0.3"
        isConnected={isConnected}
      />

      <main className="flex-1 overflow-y-auto no-print">
        {isLoading && (
          <div className="fixed inset-0 bg-white/80 backdrop-blur-sm z-[90] flex items-center justify-center">
            <div className="flex flex-col items-center">
              <div className="w-12 h-12 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin mb-4"></div>
              <p className="font-bold text-slate-700">Načítám docházku...</p>
            </div>
          </div>
        )}

        {loadError && (
          <div className="bg-red-50 text-red-600 p-4 border-b border-red-100 flex justify-between items-center text-sm font-medium">
            <span>⚠️ {loadError}</span>
            <button onClick={() => window.location.reload()} className="underline font-bold">Zkusit znovu</button>
          </div>
        )}

        {reviewingUserId && (
          <div className="bg-indigo-600 text-white px-6 py-3 sticky top-0 z-40 flex justify-between items-center shadow-md">
             <div className="font-bold text-sm flex items-center gap-2">
                <span className="bg-white/20 p-1 rounded">👁️</span> 
                Kontrola docházky: {targetUser.name}
             </div>
             <button onClick={() => setReviewingUserId(null)} className="bg-white text-indigo-600 px-4 py-1.5 rounded-lg text-xs font-bold shadow-sm">UKONČIT KONTROLU</button>
          </div>
        )}

        {activeTab === 'overview' && (
          <div className="p-4 md:p-8">
            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-4">
              <h2 className="text-2xl font-bold text-slate-900">Přehled docházky</h2>
              <MonthNavigator selectedMonth={selectedMonth} onMonthChange={setSelectedMonth} />
            </div>

            <ApprovalWorkflow 
              status={currentMonthStatus} 
              onUpdateStatus={handleUpdateStatus} 
              isManagerMode={isManagerMode} 
              isReviewing={!!reviewingUserId}
            />

            {isManagerMode && !reviewingUserId && employees.length > 0 && (
                <TeamOverview 
                  employees={employees} 
                  allEntries={entries} 
                  selectedMonth={selectedMonth} 
                  onInspect={setReviewingUserId} 
                  currentUserRole={currentUser.role}
                  statuses={monthStatuses}
                />
            )}

            {!isLocked ? (
              <SmartInput 
                onEntriesAdded={(newE) => {
                  if (!useDemoData) db.addTimeEntriesBulk(newE);
                  setEntries(prev => [...prev, ...newE]);
                }} 
                currentUserId={String(targetUserId)} 
                onManualEntry={() => {setEditingEntry(undefined); setIsEntryModalOpen(true);}} 
              />
            ) : (
              <div className="bg-amber-50 border border-amber-200 p-6 rounded-xl mb-6 flex items-center gap-4">
                <div className="text-2xl">🔒</div>
                <div>
                  <h3 className="font-bold text-amber-900">Docházka je uzamčena</h3>
                  <p className="text-sm text-amber-700">Záznamy jsou ve stavu {currentMonthStatus.status}. Pro změny kontaktujte Lucii.</p>
                </div>
              </div>
            )}

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mb-8">
                <div className="lg:col-span-2"><Dashboard entries={monthlyUserEntries} selectedMonth={selectedMonth} /></div>
                <div><ValidationStatus issues={validationIssues} /></div>
            </div>

            <h3 className="text-lg font-semibold text-slate-900 mb-4 flex items-center gap-2">
              Výkaz: {targetUser.name}
              {isLocked && <span className="text-[10px] bg-slate-200 text-slate-600 px-2 py-0.5 rounded uppercase font-bold">Jen pro čtení</span>}
            </h3>
            <TimesheetTable 
              entries={monthlyUserEntries} 
              onDelete={handleDeleteEntry} 
              onEdit={handleEditEntry} 
              isLocked={isLocked}
            />
          </div>
        )}

        {activeTab === 'report' && (
           <div className="p-4 md:p-8">
              <ReportingModule 
                entries={entries} 
                employees={employees} 
                currentUserRole={currentUser.role} 
                jobs={jobs} 
                selectedEmployeeId={String(targetUserId)} 
                selectedMonth={selectedMonth} 
                monthStatus={currentMonthStatus}
              />
           </div>
        )}

        {activeTab === 'settings' && isManagerMode && (
           <div className="p-4 md:p-8"><AdminPanel employees={employees} jobs={jobs} /></div>
        )}
      </main>

      <EntryFormModal 
        isOpen={isEntryModalOpen} 
        onClose={() => {setIsEntryModalOpen(false); setEditingEntry(undefined);}} 
        onSubmit={handleModalSubmit} 
        currentUserId={String(targetUserId)} 
        jobs={jobs} 
        initialEntry={editingEntry} 
      />

      <PinPadModal 
        isOpen={isPinModalOpen} 
        onClose={() => setIsPinModalOpen(false)} 
        onSuccess={() => {setCurrentUserId(pendingUserId!); setIsPinModalOpen(false);}} 
        targetPin={(employees.find(e=>String(e.id)===String(pendingUserId)) || MOCK_EMPLOYEES.find(e=>String(e.id)===String(pendingUserId)))?.pinCode || ""} 
        targetUserName={(employees.find(e=>String(e.id)===String(pendingUserId)) || MOCK_EMPLOYEES.find(e=>String(e.id)===String(pendingUserId)))?.name || ""} 
      />

      <HelpSystem />
      <AboutModal isOpen={isAboutOpen} onClose={() => setIsAboutOpen(false)} version="2.0.3" />
      <MobileNavigation activeTab={activeTab} setActiveTab={setActiveTab} currentUserRole={currentUser.role} />
    </div>
  );
};

