  }, [selectedMonth]);

  useEffect(() => {
    if (currentUserId) localStorage.setItem('lastUserId', currentUserId);
  }, [currentUserId]);

  const currentUser = useMemo(() => {
    const list = useDemoData ? MOCK_EMPLOYEES : employees;
    const found = list.find(e => String(e.id) === String(currentUserId));
    return found || list[0] || MOCK_EMPLOYEES[0];
  }, [useDemoData, employees, currentUserId]);

  const targetUserId = reviewingUserId || currentUserId;
  const targetUser = useMemo(() => {
    const list = useDemoData ? MOCK_EMPLOYEES : employees;
    return list.find(e => String(e.id) === String(targetUserId)) || currentUser;
  }, [useDemoData, employees, targetUserId, currentUser]);

  const isManagerMode = currentUser.role === 'Manager';

  const currentMonthStatus = useMemo(() => {
    const status = monthStatuses.find(s => String(s.employeeId) === String(targetUserId) && s.month === selectedMonth);
    return status || { employeeId: targetUserId, month: selectedMonth, status: TimesheetStatus.DRAFT };
  }, [monthStatuses, targetUserId, selectedMonth]);

  const isLocked = useMemo(() => {
    const isSubmittedOrApproved = currentMonthStatus.status === TimesheetStatus.SUBMITTED || 
                                currentMonthStatus.status === TimesheetStatus.APPROVED;
    if (isManagerMode && reviewingUserId) return false; 
    return isSubmittedOrApproved;
  }, [currentMonthStatus, isManagerMode, reviewingUserId]);

  const monthlyUserEntries = useMemo(() => {
    return entries.filter(e => String(e.employeeId) === String(targetUserId) && e.date.startsWith(selectedMonth));
  }, [entries, targetUserId, selectedMonth]);

  const validationIssues = useMemo(() => {
    const [year, month] = selectedMonth.split('-');
    return validateMonth(monthlyUserEntries, year, month);
  }, [monthlyUserEntries, selectedMonth]);

  const handleUpdateStatus = async (newStatus: TimesheetStatus, comment?: string) => {
    const updatedStatus: MonthStatus = {
      ...currentMonthStatus,
      status: newStatus,
      managerComment: comment,
      submittedAt: newStatus === TimesheetStatus.SUBMITTED ? new Date().toISOString() : currentMonthStatus.submittedAt,
      approvedAt: newStatus === TimesheetStatus.APPROVED ? new Date().toISOString() : currentMonthStatus.approvedAt,
    };

    if (!useDemoData) {
      try {
        await db.upsertMonthlyReport(updatedStatus);
      } catch (e: any) {
        alert("Chyba při ukládání stavu: " + e.message);
        return;
      }
    }

    setMonthStatuses(prev => [
      ...prev.filter(s => !(String(s.employeeId) === String(targetUserId) && s.month === selectedMonth)),
      updatedStatus
    ]);

    if (newStatus === TimesheetStatus.APPROVED || newStatus === TimesheetStatus.REJECTED) {
      setReviewingUserId(null);
    }
  };

  const handleModalSubmit = async (date: string, submittedEntries: TimeEntry[]) => {
      if (isLocked) return;

      if (!useDemoData) {
        try {
          if (editingEntry) {
              await db.deleteTimeEntry(editingEntry.id);
          }
          // Poznámka: Mazání celého dne bylo odstraněno, abychom umožnili multi-zápis
          await db.addTimeEntriesBulk(submittedEntries);
        } catch (e: any) {
          alert(`Chyba DB: ${e.message}`);
          return;
        }
      }

      if (date === 'BULK_RANGE') {
          setEntries(prev => [...prev, ...submittedEntries]);
      } else {
          setEntries(prev => [
              ...prev.filter(e => !(String(e.employeeId) === String(targetUserId) && (editingEntry ? e.id === editingEntry.id : false))),
              ...submittedEntries
          ]);
      }
      setEditingEntry(undefined);
  };

  const handleDeleteEntry = async (id: string) => {
    if (isLocked) return;
    if (!useDemoData) {
      try { await db.deleteTimeEntry(id); } catch (e) { return; }
    }
    setEntries(prev => prev.filter(e => e.id !== id));
  };

  const handleEditEntry = (entry: TimeEntry) => {
    if (isLocked) return;
    setEditingEntry(entry);
    setIsEntryModalOpen(true);
  };

  return (
    <div className="flex flex-col md:flex-row min-h-screen bg-gray-50">
      <Sidebar 
        activeTab={activeTab} setActiveTab={setActiveTab} 
        currentUser={currentUser} 
        employees={(useDemoData ? MOCK_EMPLOYEES : employees).filter(e => e.isActive)}
        onRequestSwitchUser={(id) => {
            const list = useDemoData ? MOCK_EMPLOYEES : employees;
            const targetEmp = list.find(e => String(e.id) === String(id));
            if (targetEmp?.pinCode) { 
                setPendingUserId(id); 
                setIsPinModalOpen(true); 
            } else {
                setCurrentUserId(id);
            }
        }} 
        onShowAbout={() => setIsAboutOpen(true)}
        version="2.1.0"
        isConnected={isConnected}
      />

      <main className="flex-1 overflow-y-auto no-print">
        {isLoading && (
          <div className="fixed inset-0 bg-white/80 backdrop-blur-sm z-[90] flex items-center justify-center">
            <div className="flex flex-col items-center">
              <div className="w-12 h-12 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin mb-4"></div>
              <p className="font-bold text-slate-700">Synchronizace...</p>
            </div>
          </div>
        )}

        {loadError && (
          <div className="bg-red-50 text-red-600 p-4 border-b border-red-100 flex justify-between items-center text-sm font-medium">
            <span>⚠️ {loadError}</span>
            <button onClick={() => window.location.reload()} className="underline font-bold">Zkusit znovu</button>
          </div>
        )}

        {reviewingUserId && (
          <div className="bg-indigo-600 text-white px-6 py-3 sticky top-0 z-40 flex justify-between items-center shadow-md">
             <div className="font-bold text-sm flex items-center gap-2">
                <span className="bg-white/20 p-1 rounded">👁️</span> 
                Kontrola docházky: {targetUser.name}
             </div>
             <button onClick={() => setReviewingUserId(null)} className="bg-white text-indigo-600 px-4 py-1.5 rounded-lg text-xs font-bold shadow-sm">UKONČIT KONTROLU</button>
          </div>
        )}

        {activeTab === 'overview' && (
          <div className="p-4 md:p-8">
            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-4">
              <h2 className="text-2xl font-bold text-slate-900">Přehled docházky</h2>
              <MonthNavigator selectedMonth={selectedMonth} onMonthChange={setSelectedMonth} />
            </div>

            <ApprovalWorkflow 
              status={currentMonthStatus} 
              onUpdateStatus={handleUpdateStatus} 
              isManagerMode={isManagerMode} 
              isReviewing={!!reviewingUserId}
            />

            {isManagerMode && !reviewingUserId && employees.length > 0 && (
                <TeamOverview 
                  employees={employees} 
                  allEntries={entries} 
                  selectedMonth={selectedMonth} 
                  onInspect={setReviewingUserId} 
                  currentUserRole={currentUser.role}
                  statuses={monthStatuses}
                />
            )}

            {!isLocked ? (
              <SmartInput 
                onEntriesAdded={(newE) => {
                  if (!useDemoData) db.addTimeEntriesBulk(newE);
                  setEntries(prev => [...prev, ...newE]);
                }} 
                currentUserId={String(targetUserId)} 
                onManualEntry={() => {setEditingEntry(undefined); setIsEntryModalOpen(true);}} 
              />
            ) : (
              <div className="bg-amber-50 border border-amber-200 p-6 rounded-xl mb-6 flex items-center gap-4">
                <div className="text-2xl">🔒</div>
                <div>
                  <h3 className="font-bold text-amber-900">Docházka je uzamčena</h3>
                  <p className="text-sm text-amber-700">Záznamy jsou ve stavu {currentMonthStatus.status}. Pro změny kontaktujte Lucii.</p>
                </div>
              </div>
            )}

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mb-8">
                <div className="lg:col-span-2"><Dashboard entries={monthlyUserEntries} selectedMonth={selectedMonth} /></div>
                <div><ValidationStatus issues={validationIssues} /></div>
            </div>

            <h3 className="text-lg font-semibold text-slate-900 mb-4 flex items-center gap-2">
              Výkaz: {targetUser.name}
              {isLocked && <span className="text-[10px] bg-slate-200 text-slate-600 px-2 py-0.5 rounded uppercase font-bold">Jen pro čtení</span>}
            </h3>
            <TimesheetTable 
              entries={monthlyUserEntries} 
              onDelete={handleDeleteEntry} 
              onEdit={handleEditEntry} 
              isLocked={isLocked}
            />
          </div>
        )}

        {activeTab === 'report' && (
           <div className="p-4 md:p-8">
              <ReportingModule 
                entries={entries} 
                employees={employees} 
                currentUserRole={currentUser.role} 
                jobs={jobs} 
                selectedEmployeeId={String(targetUserId)} 
                selectedMonth={selectedMonth} 
                monthStatus={currentMonthStatus}
              />
           </div>
        )}

        {activeTab === 'settings' && isManagerMode && (
           <div className="p-4 md:p-8"><AdminPanel employees={employees} jobs={jobs} /></div>
        )}
      </main>

      <EntryFormModal 
        isOpen={isEntryModalOpen} 
        onClose={() => {setIsEntryModalOpen(false); setEditingEntry(undefined);}} 
        onSubmit={handleModalSubmit} 
        currentUserId={String(targetUserId)} 
        jobs={jobs} 
        initialEntry={editingEntry} 
      />

      <PinPadModal 
        isOpen={isPinModalOpen} 
        onClose={() => setIsPinModalOpen(false)} 
        onSuccess={() => {setCurrentUserId(pendingUserId!); setIsPinModalOpen(false);}} 
        targetPin={(employees.find(e=>String(e.id)===String(pendingUserId)) || MOCK_EMPLOYEES.find(e=>String(e.id)===String(pendingUserId)))?.pinCode || ""} 
        targetUserName={(employees.find(e=>String(e.id)===String(pendingUserId)) || MOCK_EMPLOYEES.find(e=>String(e.id)===String(pendingUserId)))?.name || ""} 
      />

      <HelpSystem />
      <AboutModal isOpen={isAboutOpen} onClose={() => setIsAboutOpen(false)} version="2.1.0" />
      <MobileNavigation activeTab={activeTab} setActiveTab={setActiveTab} currentUserRole={currentUser.role} />
    </div>
  );
};

export default App;

import React, { useMemo } from 'react';
import { TimeEntry, Employee, Job, WorkType, MonthStatus, TimesheetStatus } from '../types';
import { getHolidayName } from '../services/holidayService';

interface ReportingModuleProps {
  entries: TimeEntry[];
  employees: Employee[];
  currentUserRole: string;
  jobs: Job[];
  selectedEmployeeId?: string;
  selectedMonth?: string;
  monthStatus?: MonthStatus;
}

const ReportingModule: React.FC<ReportingModuleProps> = ({ entries, employees, selectedEmployeeId, selectedMonth, monthStatus }) => {
  const monthStr = selectedMonth || new Date().toISOString().slice(0, 7);
  const [year, month] = monthStr.split('-').map(Number);

  const employee = useMemo(() => 
    employees.find(e => String(e.id) === String(selectedEmployeeId)) || employees[0], 
  [employees, selectedEmployeeId]);

  const filteredEntries = useMemo(() => 
    entries.filter(e => String(e.employeeId) === String(employee?.id) && e.date.startsWith(monthStr)),
  [entries, employee, monthStr]);

  const monthStats = useMemo(() => {
    const daysInMonth = new Date(year, month, 0).getDate();
    let workingDays = 0;
    const days = [];

    for (let d = 1; d <= daysInMonth; d++) {
      const dateStr = `${year}-${String(month).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
      const dateObj = new Date(year, month - 1, d);
      const isWeekend = dateObj.getDay() === 0 || dateObj.getDay() === 6;
      const holiday = getHolidayName(dateStr);
      if (!isWeekend && !holiday) workingDays++;

      const dayEntries = filteredEntries.filter(e => e.date === dateStr);

      // Rozdělení hodin do maticových sloupců
      const stats = {
        work: dayEntries.filter(e => e.type === WorkType.REGULAR || e.type === WorkType.OVERTIME).reduce((s, e) => s + e.hours, 0),
        doctor: dayEntries.filter(e => e.type === WorkType.DOCTOR).reduce((s, e) => s + e.hours, 0),
        vacation: dayEntries.filter(e => e.type === WorkType.VACATION).reduce((s, e) => s + e.hours, 0),
        sick: dayEntries.filter(e => e.type === WorkType.SICK_DAY).reduce((s, e) => s + e.hours, 0),
        other: dayEntries.filter(e => ![WorkType.REGULAR, WorkType.OVERTIME, WorkType.DOCTOR, WorkType.VACATION, WorkType.SICK_DAY].includes(e.type)).reduce((s, e) => s + e.hours, 0),
        total: dayEntries.reduce((s, e) => s + e.hours, 0),
        projects: Array.from(new Set(dayEntries.filter(e => e.project).map(e => e.project))).join(', ')
      };

      days.push({
        dateStr,
        isWeekend,
        holiday,
        ...stats
      });
    }

    const fund = workingDays * 8;
    const totalHours = filteredEntries.reduce((sum, e) => sum + e.hours, 0);
    return { fund, totalHours, days, diff: totalHours - fund };
  }, [year, month, filteredEntries]);

  const typeSummary = useMemo(() => {
    const summary: Record<string, number> = {};
    Object.values(WorkType).forEach(t => summary[t] = 0);
    filteredEntries.forEach(e => summary[e.type] += e.hours);
    return summary;
  }, [filteredEntries]);

  const shorten = (text: string, len: number = 30) => 
    text.length > len ? text.substring(0, len - 3) + '...' : text;

  return (
    <div className="space-y-6 max-w-5xl mx-auto pb-20">
      <div className="bg-white p-6 rounded-xl border border-gray-200 shadow-sm flex justify-between items-center no-print">
        <div>
          <h2 className="text-xl font-bold text-slate-900">Mzdový report (Matrix)</h2>
          <p className="text-xs text-slate-500">Zaměstnanec: {employee?.name} | {monthStr}</p>
        </div>
        <button onClick={() => window.print()} className="bg-indigo-600 hover:bg-indigo-700 text-white px-6 py-2 rounded-lg font-bold text-sm transition-colors shadow-lg">Vytisknout A4</button>
      </div>

      <div className="bg-white p-6 md:p-8 rounded-none md:rounded-xl shadow-none md:shadow-sm border-0 md:border border-gray-100 print:p-0 print:m-0 relative overflow-hidden">

        {monthStatus?.status === TimesheetStatus.APPROVED && (
          <div className="absolute top-10 right-10 border-4 border-green-600/30 text-green-600/30 font-black text-4xl px-4 py-2 rounded-xl -rotate-12 pointer-events-none select-none uppercase tracking-widest hidden print:block">
            SCHVÁLENO
          </div>
        )}

        <div className="flex justify-between items-start border-b-2 border-slate-900 pb-4 mb-6">
          <div>
            <h1 className="text-2xl font-black text-slate-900 uppercase">Výkaz práce</h1>
            <p className="text-sm font-bold text-indigo-600">{employee?.name}</p>
          </div>
          <div className="text-right">
            <p className="text-xl font-black text-slate-900">{monthStr}</p>
            <p className="text-[10px] text-slate-400 uppercase font-bold">Export: {new Date().toLocaleDateString('cs-CZ')}</p>
          </div>
        </div>

        <div className="grid grid-cols-4 gap-4 mb-8">
          <div className="border-l-4 border-indigo-600 pl-3">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">Celkem hodin</p>
            <p className="text-2xl font-black text-slate-900">{monthStats.totalHours.toFixed(1)}h</p>
          </div>
          <div className="border-l-4 border-slate-300 pl-3">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">Fond</p>
            <p className="text-2xl font-black text-slate-900">{monthStats.fund}h</p>
          </div>
          <div className="border-l-4 border-orange-500 pl-3">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">Přesčasy</p>
            <p className="text-2xl font-black text-orange-600">{typeSummary[WorkType.OVERTIME].toFixed(1)}h</p>
          </div>
          <div className={`border-l-4 pl-3 ${monthStats.diff >= 0 ? 'border-green-500' : 'border-red-500'}`}>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">Rozdíl</p>
            <p className={`text-2xl font-black ${monthStats.diff >= 0 ? 'text-green-600' : 'text-red-600'}`}>
              {monthStats.diff > 0 ? '+' : ''}{monthStats.diff.toFixed(1)}h
            </p>
          </div>
        </div>

        <div>
          <h3 className="text-xs font-black text-slate-900 uppercase mb-3 bg-slate-100 p-2 border-l-2 border-slate-900">Denní přehled (Matrix view)</h3>
          <table className="w-full border-collapse">
            <thead>
              <tr className="bg-slate-800 text-white">
                <th className="text-[9px] p-1 text-left w-14">DATUM</th>
                <th className="text-[9px] p-1 text-left">PROJEKTY</th>
                <th className="text-[9px] p-1 text-center w-10">PRÁCE</th>
                <th className="text-[9px] p-1 text-center w-10">LÉK.</th>
                <th className="text-[9px] p-1 text-center w-10">DOV.</th>
                <th className="text-[9px] p-1 text-center w-10">NEM.</th>
                <th className="text-[9px] p-1 text-center w-10">OST.</th>
                <th className="text-[9px] p-1 text-right w-14">CELKEM</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-200 border-b border-slate-200">
              {monthStats.days.map(day => (
                <tr key={day.dateStr} className={`${day.isWeekend ? 'bg-slate-50' : ''} ${day.holiday ? 'bg-amber-50' : ''}`}>
                  <td className="text-[10px] p-1 font-bold whitespace-nowrap">
                    {new Date(day.dateStr).toLocaleDateString('cs-CZ', { day: '2-digit', weekday: 'short' })}
                  </td>
                  <td className="text-[9px] p-1 text-slate-600">
                    {shorten(day.projects, 50)} {day.holiday && <span className="text-amber-600 font-bold ml-1">({day.holiday})</span>}
                  </td>
                  <td className={`text-[10px] p-1 text-center ${day.work > 0 ? 'font-bold' : 'text-slate-300'}`}>{day.work || '-'}</td>
                  <td className={`text-[10px] p-1 text-center ${day.doctor > 0 ? 'font-bold text-indigo-600' : 'text-slate-300'}`}>{day.doctor || '-'}</td>
                  <td className={`text-[10px] p-1 text-center ${day.vacation > 0 ? 'font-bold text-green-600' : 'text-slate-300'}`}>{day.vacation || '-'}</td>
                  <td className={`text-[10px] p-1 text-center ${day.sick > 0 ? 'font-bold text-red-600' : 'text-slate-300'}`}>{day.sick || '-'}</td>
                  <td className={`text-[10px] p-1 text-center ${day.other > 0 ? 'font-bold text-slate-600' : 'text-slate-300'}`}>{day.other || '-'}</td>
                  <td className={`text-[10px] p-1 text-right font-black ${day.total > 0 ? 'text-slate-900' : 'text-slate-300'}`}>
                    {day.total > 0 ? `${day.total.toFixed(1)}h` : '-'}
                  </td>
                </tr>
              ))}
            </tbody>
            <tfoot>
              <tr className="bg-slate-50 font-black">
                <td colSpan={2} className="text-[10px] p-2 text-right uppercase">Součty za měsíc:</td>
                <td className="text-[10px] p-2 text-center">{typeSummary[WorkType.REGULAR] + typeSummary[WorkType.OVERTIME]}h</td>
                <td className="text-[10px] p-2 text-center text-indigo-600">{typeSummary[WorkType.DOCTOR]}h</td>
                <td className="text-[10px] p-2 text-center text-green-600">{typeSummary[WorkType.VACATION]}h</td>
                <td className="text-[10px] p-2 text-center text-red-600">{typeSummary[WorkType.SICK_DAY]}h</td>
                <td className="text-[10px] p-2 text-center text-slate-500">
                  {Object.entries(typeSummary).reduce((s, [k, v]) => ![WorkType.REGULAR, WorkType.OVERTIME, WorkType.DOCTOR, WorkType.VACATION, WorkType.SICK_DAY].includes(k as WorkType) ? s + v : s, 0)}h
                </td>
                <td className="text-[10px] p-2 text-right">{monthStats.totalHours.toFixed(1)}h</td>
              </tr>
            </tfoot>
          </table>
        </div>

        <div className="mt-12 flex justify-between gap-12 border-t border-slate-100 pt-8">
          <div className="flex-1 border-t border-slate-300 pt-2">
            <p className="text-[9px] font-bold text-slate-400 uppercase">Podpis zaměstnance</p>
          </div>
          <div className="flex-1 border-t border-slate-300 pt-2 text-right">
            <p className="text-[9px] font-bold text-slate-400 uppercase">Schválil (Lucie)</p>
            {monthStatus?.status === TimesheetStatus.APPROVED && (
              <p className="text-[10px] font-black text-slate-900 mt-2">ELEKTRONICKY POTVRZENO</p>
            )}
          </div>
        </div>

      </div>
    </div>
  );
};
export default ReportingModule;

import React from 'react';
import { TimeEntry, WorkType } from '../types';

interface TimesheetTableProps {
  entries: TimeEntry[];
  onDelete: (id: string) => void;
  onEdit: (entry: TimeEntry) => void;
  isLocked?: boolean;
}

const TimesheetTable: React.FC<TimesheetTableProps> = ({ entries, onDelete, onEdit, isLocked }) => {
  const sorted = [...entries].sort((a, b) => b.date.localeCompare(a.date));

  const getTypeBadge = (type: WorkType) => {
    const colors: Record<string, string> = {
      [WorkType.REGULAR]: 'bg-slate-100 text-slate-600',
      [WorkType.VACATION]: 'bg-green-100 text-green-700',
      [WorkType.DOCTOR]: 'bg-indigo-100 text-indigo-700',
      [WorkType.SICK_DAY]: 'bg-red-100 text-red-700',
      [WorkType.OVERTIME]: 'bg-orange-100 text-orange-700',
    };
    return <span className={`text-[9px] px-1.5 py-0.5 rounded font-bold uppercase ${colors[type] || 'bg-gray-100 text-gray-600'}`}>{type}</span>;
  };

  return (
    <div className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden mb-20 md:mb-8">
      <table className="w-full text-sm text-left">
        <thead className="bg-gray-50 border-b border-gray-200">
          <tr>
            <th className="p-4 font-bold text-gray-500 uppercase text-[10px]">Datum</th>
            <th className="p-4 font-bold text-gray-500 uppercase text-[10px]">Projekt & Typ</th>
            <th className="p-4 font-bold text-gray-500 uppercase text-[10px]">Popis</th>
            <th className="p-4 font-bold text-gray-500 uppercase text-[10px] text-right">Hodiny</th>
            {!isLocked && <th className="p-4"></th>}
          </tr>
        </thead>
        <tbody className="divide-y divide-gray-100">
          {sorted.map((e, idx) => {
            const isFirstInDay = idx === 0 || sorted[idx - 1].date !== e.date;
            const isLastInDay = idx === sorted.length - 1 || sorted[idx + 1].date !== e.date;

            return (
              <tr key={e.id} className={`hover:bg-slate-50 transition-colors ${!isFirstInDay ? 'bg-slate-50/30' : ''}`}>
                <td className="p-4 align-top">
                  {isFirstInDay ? (
                    <div className="font-bold text-slate-900">{new Date(e.date).toLocaleDateString('cs-CZ', { day: '2-digit', month: '2-digit', weekday: 'short' })}</div>
                  ) : (
                    <div className="w-1 h-full bg-slate-200 ml-4 rounded-full"></div>
                  )}
                </td>
                <td className="p-4">
                  <div className="font-medium text-slate-700">{e.project || '-'}</div>
                  <div className="mt-1">{getTypeBadge(e.type)}</div>
                </td>
                <td className="p-4 text-slate-500 italic text-xs">{e.description || '-'}</td>
                <td className="p-4 text-right font-black text-slate-900">{e.hours.toFixed(1)}h</td>
                {!isLocked && (
                  <td className="p-4 text-right whitespace-nowrap">
                    <div className="flex justify-end gap-3">
                      <button 
                        onClick={() => onEdit(e)} 
                        className="text-indigo-600 hover:text-indigo-800 font-bold text-[10px] uppercase p-1"
                      >
                        ✏️
                      </button>
                      <button 
                        onClick={() => onDelete(e.id)} 
                        className="text-red-400 hover:text-red-600 font-bold text-[10px] uppercase p-1"
                      >
                        🗑️
                      </button>
                    </div>
                  </td>
                )}
              </tr>
            );
          })}
          {sorted.length === 0 && (
            <tr><td colSpan={isLocked ? 4 : 5} className="p-12 text-center text-slate-400 font-medium">Zatím jste nezapsali žádné hodiny.</td></tr>
          )}
        </tbody>
      </table>
    </div>
  );
};
